CREATE TABLE public.metabase_field_import (
    source_id integer NOT NULL,
    source_table_id integer NOT NULL,
    source_parent_id integer,
    source_fk_target_id integer,
    name character varying(254) NOT NULL,
    base_type character varying(254) NOT NULL,
    database_type character varying(254) NOT NULL,
    effective_type character varying(254),
    semantic_type character varying(254),
    coercion_strategy character varying(254),
    description text,
    nfc_path text,
    depth integer,
    target_id integer,
    target_table_id integer,
    target_parent_id integer,
    target_fk_target_id integer
);
--;;
COMMENT ON TABLE public.metabase_field_import IS 'Staging table for the metadata file importer''s fields phase. Drained outside the merge txn, depth-tagged, then merged into metabase_field level by level inside the txn.';
--;;
COMMENT ON COLUMN public.metabase_field_import.source_id IS 'Wire :id — source appdb''s metabase_field.id. Unique within one file.';
--;;
COMMENT ON COLUMN public.metabase_field_import.source_table_id IS 'Wire :table_id — references metabase_table_import.source_id within the same file.';
--;;
COMMENT ON COLUMN public.metabase_field_import.source_parent_id IS 'Wire :parent_id — references another metabase_field_import.source_id within the same file. NULL for top-level fields.';
--;;
COMMENT ON COLUMN public.metabase_field_import.source_fk_target_id IS 'Wire :fk_target_field_id — references another metabase_field_import.source_id. NULL for non-FK fields.';
--;;
COMMENT ON COLUMN public.metabase_field_import.name IS 'Wire :name — field''s natural-key name component (within its parent + table).';
--;;
COMMENT ON COLUMN public.metabase_field_import.base_type IS 'Wire :base_type — clobbered onto metabase_field.base_type on merge.';
--;;
COMMENT ON COLUMN public.metabase_field_import.database_type IS 'Wire :database_type — clobbered onto metabase_field.database_type on merge.';
--;;
COMMENT ON COLUMN public.metabase_field_import.effective_type IS 'NULL when wire row omitted it (≡ base_type). Importer treats NULL as base_type on INSERT; leaves target alone on UPDATE.';
--;;
COMMENT ON COLUMN public.metabase_field_import.semantic_type IS 'Wire :semantic_type — clobbered onto metabase_field.semantic_type on merge.';
--;;
COMMENT ON COLUMN public.metabase_field_import.coercion_strategy IS 'Wire :coercion_strategy — clobbered onto metabase_field.coercion_strategy on merge.';
--;;
COMMENT ON COLUMN public.metabase_field_import.description IS 'Wire :description — clobbered onto metabase_field.description on merge.';
--;;
COMMENT ON COLUMN public.metabase_field_import.nfc_path IS 'NULL for empty/absent paths, JSON-encoded array string otherwise — same encoding as metabase_field.nfc_path.';
--;;
COMMENT ON COLUMN public.metabase_field_import.depth IS 'Populated once after drain by the depth-tagging step. 0 = root (no parent, no fk_target). Higher = max(parent depth, fk_target depth) + 1. NULL after depth-tagging means a cycle in the file''s reference graph.';
--;;
COMMENT ON COLUMN public.metabase_field_import.target_id IS 'Resolved per-depth-level by natural-key match against metabase_field. NULL means no live row matches; row is an insert candidate at this depth.';
--;;
COMMENT ON COLUMN public.metabase_field_import.target_table_id IS 'Populated from the table-resolve step before the depth walk starts. Joined-through from metabase_table_import.target_id.';
--;;
COMMENT ON COLUMN public.metabase_field_import.target_parent_id IS 'Populated per-depth-level by self-join on source_parent_id → another row''s target_id.';
--;;
COMMENT ON COLUMN public.metabase_field_import.target_fk_target_id IS 'Populated per-depth-level by self-join on source_fk_target_id → another row''s target_id.';
--;;
