CREATE VIEW public.v_metabot_conversations AS
SELECT
    NULL::character varying(36) AS conversation_id,
    NULL::timestamp with time zone AS created_at,
    NULL::integer AS user_id,
    NULL::text AS summary,
    NULL::text AS user_display_name,
    NULL::bigint AS message_count,
    NULL::bigint AS user_message_count,
    NULL::bigint AS assistant_message_count,
    NULL::bigint AS total_tokens,
    NULL::bigint AS prompt_tokens,
    NULL::bigint AS completion_tokens,
    NULL::timestamp with time zone AS last_message_at,
    NULL::text AS profile_id,
    NULL::text AS profile_name,
    NULL::character varying(255) AS group_name,
    NULL::character varying(100) AS source,
    NULL::character varying AS source_name,
    NULL::character varying(45) AS ip_address,
    NULL::character varying(512) AS embedding_hostname,
    NULL::character varying(2048) AS embedding_path,
    NULL::character varying(512) AS user_agent,
    NULL::character varying(512) AS sanitized_user_agent,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_name,
    NULL::character varying(255) AS model;
