CREATE VIEW public.v_metabot_messages AS
 SELECT m.id AS message_id,
    m.conversation_id,
    m.created_at,
    m.role,
    m.profile_id,
    m.total_tokens,
    COALESCE(m.user_id, c.user_id) AS user_id,
    m.slack_msg_id,
    m.channel_id
   FROM (public.metabot_message m
     JOIN public.metabot_conversation c ON (((c.id)::text = (m.conversation_id)::text)))
  WHERE (m.deleted_at IS NULL);
--;;
CREATE VIEW public.v_query_log AS
 SELECT query_execution.id AS entity_id,
    query_execution.started_at,
    ((query_execution.running_time)::double precision / (1000)::double precision) AS running_time_seconds,
    query_execution.result_rows,
    query_execution.native AS is_native,
    query_execution.context AS query_source,
    query_execution.error,
    COALESCE(query_execution.executor_id, 0) AS user_id,
    query_execution.card_id,
    ('card_'::text || query_execution.card_id) AS card_qualified_id,
    query_execution.dashboard_id,
    ('dashboard_'::text || query_execution.dashboard_id) AS dashboard_qualified_id,
    query_execution.pulse_id,
    query_execution.database_id,
    ('database_'::text || query_execution.database_id) AS database_qualified_id,
    query_execution.cache_hit,
    query_execution.action_id,
    ('action_'::text || query_execution.action_id) AS action_qualified_id,
    query_execution.transform_id,
    ('transform_'::text || query_execution.transform_id) AS transform_qualified_id,
    query_execution.lens_id,
    query_execution.lens_params,
    query.query,
    query_execution.embedding_client,
    query_execution.embedding_route,
        CASE
            WHEN ((query_execution.embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    query_execution.embedding_sdk_version,
    query_execution.metabase_version,
    query_execution.auth_method,
    query_execution.is_sandboxed,
    query_execution.is_impersonated,
    query_execution.is_db_routed,
    query_execution.parameters,
    query_execution.tenant_id,
    query_execution.embedding_hostname,
    query_execution.embedding_path,
    query_execution.user_agent,
    query_execution.sanitized_user_agent,
    query_execution.ip_address
   FROM (public.query_execution
     LEFT JOIN public.query ON ((query_execution.hash = query.query_hash)));
--;;
CREATE VIEW public.v_subscriptions AS
 WITH agg_recipients AS (
         SELECT pulse_channel_recipient.pulse_channel_id,
            string_agg((core_user.email)::text, ','::text) AS recipients
           FROM (public.pulse_channel_recipient
             LEFT JOIN public.core_user ON ((pulse_channel_recipient.user_id = core_user.id)))
          GROUP BY pulse_channel_recipient.pulse_channel_id
        )
 SELECT pulse.id AS entity_id,
    ('pulse_'::text || pulse.id) AS entity_qualified_id,
    pulse.created_at,
    pulse.updated_at,
    pulse.creator_id,
    pulse.archived,
    ('dashboard_'::text || pulse.dashboard_id) AS dashboard_qualified_id,
    pulse_channel.schedule_type,
    pulse_channel.schedule_day,
    pulse_channel.schedule_hour,
    pulse_channel.channel_type AS recipient_type,
    agg_recipients.recipients,
    pulse_channel.details AS recipient_external,
    pulse.parameters
   FROM ((public.pulse
     LEFT JOIN public.pulse_channel ON ((pulse.id = pulse_channel.pulse_id)))
     LEFT JOIN agg_recipients ON ((pulse_channel.id = agg_recipients.pulse_channel_id)))
  WHERE (pulse.alert_condition IS NULL);
--;;
CREATE VIEW public.v_tables AS
 SELECT metabase_table.id AS entity_id,
    ('table_'::text || metabase_table.id) AS entity_qualified_id,
    metabase_table.created_at,
    metabase_table.updated_at,
    metabase_table.name,
    metabase_table.display_name,
    metabase_table.description,
    metabase_table.active,
    metabase_table.db_id AS database_id,
    metabase_table.schema,
    metabase_table.is_upload,
    metabase_table.entity_type,
    metabase_table.visibility_type,
    metabase_table.estimated_row_count,
    metabase_table.view_count,
    metabase_table.owner_email,
    metabase_table.owner_user_id
   FROM public.metabase_table;
--;;
CREATE VIEW public.v_task_runs AS
 SELECT task_run.id,
    task_run.run_type,
    task_run.entity_type,
    task_run.entity_id,
        CASE
            WHEN ((task_run.entity_type)::text = 'database'::text) THEN ('database_'::text || task_run.entity_id)
            WHEN ((task_run.entity_type)::text = 'card'::text) THEN ('card_'::text || task_run.entity_id)
            WHEN ((task_run.entity_type)::text = 'dashboard'::text) THEN ('dashboard_'::text || task_run.entity_id)
            ELSE (((task_run.entity_type)::text || '_'::text) || task_run.entity_id)
        END AS entity_qualified_id,
    task_run.started_at,
    task_run.ended_at,
        CASE
            WHEN (task_run.ended_at IS NOT NULL) THEN (EXTRACT(epoch FROM (task_run.ended_at - task_run.started_at)))::double precision
            ELSE NULL::double precision
        END AS duration_seconds,
    task_run.status,
    task_run.process_uuid,
    task_run.updated_at
   FROM public.task_run;
--;;
CREATE VIEW public.v_tasks AS
 SELECT task_history.id,
    task_history.task,
    task_history.status,
    ('database_'::text || task_history.db_id) AS database_qualified_id,
    task_history.started_at,
    task_history.ended_at,
    ((task_history.duration)::double precision / (1000)::double precision) AS duration_seconds,
    task_history.task_details AS details,
    task_history.run_id
   FROM public.task_history;
--;;
CREATE VIEW public.v_tenants AS
 SELECT tenant.id AS tenant_id,
    ('tenant_'::text || tenant.id) AS entity_qualified_id,
    tenant.name,
    tenant.slug,
    tenant.is_active,
    tenant.attributes,
    tenant.created_at,
    tenant.updated_at,
    tenant.tenant_collection_id,
    ('collection_'::text || tenant.tenant_collection_id) AS tenant_collection_qualified_id
   FROM public.tenant;
--;;
CREATE VIEW public.v_users AS
 SELECT core_user.id AS user_id,
    ('user_'::text || core_user.id) AS entity_qualified_id,
    core_user.type,
        CASE
            WHEN ((core_user.type)::text = 'api-key'::text) THEN NULL::public.citext
            ELSE core_user.email
        END AS email,
    core_user.first_name,
    core_user.last_name,
    COALESCE((((core_user.first_name)::text || ' '::text) || (core_user.last_name)::text), (core_user.first_name)::text, (core_user.last_name)::text) AS full_name,
    core_user.date_joined,
    core_user.last_login,
    core_user.updated_at,
    core_user.is_superuser AS is_admin,
    core_user.is_active,
    core_user.sso_source,
    core_user.locale,
    core_user.tenant_id,
    ('tenant_'::text || core_user.tenant_id) AS tenant_qualified_id
   FROM public.core_user
UNION
 SELECT 0 AS user_id,
    'user_0'::text AS entity_qualified_id,
    'anonymous'::character varying AS type,
    NULL::public.citext AS email,
    'External'::character varying AS first_name,
    'User'::character varying AS last_name,
    'External User'::text AS full_name,
    NULL::timestamp with time zone AS date_joined,
    NULL::timestamp with time zone AS last_login,
    NULL::timestamp with time zone AS updated_at,
    false AS is_admin,
    NULL::boolean AS is_active,
    NULL::character varying AS sso_source,
    NULL::character varying AS locale,
    NULL::integer AS tenant_id,
    NULL::text AS tenant_qualified_id;
--;;
CREATE TABLE public.view_log (
    id integer NOT NULL,
    user_id integer,
    model character varying(16) NOT NULL,
    model_id integer NOT NULL,
    "timestamp" timestamp with time zone NOT NULL,
    metadata text,
    has_access boolean,
    context character varying(32),
    embedding_client character varying(254),
    embedding_sdk_version character varying(254),
    auth_method character varying(32),
    tenant_id integer,
    embedding_hostname character varying(512),
    embedding_path character varying(2048),
    user_agent character varying(512),
    ip_address character varying(45),
    sanitized_user_agent character varying(512),
    embedding_route character varying(64),
    metabase_version character varying(32)
);
--;;
COMMENT ON COLUMN public.view_log.has_access IS 'Whether the user who initiated the view had read access to the item being viewed.';
--;;
COMMENT ON COLUMN public.view_log.context IS 'The context of the view, can be collection, question, or dashboard. Only for cards.';
--;;
COMMENT ON COLUMN public.view_log.embedding_client IS 'Used by the embedding team to track SDK usage';
--;;
COMMENT ON COLUMN public.view_log.embedding_sdk_version IS 'Used by the embedding team to track SDK version usage';
--;;
COMMENT ON COLUMN public.view_log.auth_method IS 'Authentication method used (e.g. jwt, saml, api-key, public, guest, etc.)';
--;;
COMMENT ON COLUMN public.view_log.tenant_id IS 'Tenant ID of the user who generated this view';
--;;
COMMENT ON COLUMN public.view_log.embedding_hostname IS 'Hostname from Origin header, PII';
--;;
COMMENT ON COLUMN public.view_log.embedding_path IS 'Path from Referer header (query params stripped), PII';
--;;
COMMENT ON COLUMN public.view_log.user_agent IS 'User-Agent header, PII';
--;;
COMMENT ON COLUMN public.view_log.ip_address IS 'Client IP address, PII';
--;;
COMMENT ON COLUMN public.view_log.sanitized_user_agent IS 'Human-friendly parsed User-Agent (e.g. Browser (Chrome/Windows)), PII';
--;;
COMMENT ON COLUMN public.view_log.embedding_route IS 'API route surface (e.g. public, guest-embed, metabot, agent-api)';
--;;
COMMENT ON COLUMN public.view_log.metabase_version IS 'Metabase server version tag at time of insert';
--;;
CREATE VIEW public.v_view_log AS
 SELECT view_log.id,
    view_log."timestamp",
    COALESCE(view_log.user_id, 0) AS user_id,
    view_log.model AS entity_type,
    view_log.model_id AS entity_id,
    (((view_log.model)::text || '_'::text) || view_log.model_id) AS entity_qualified_id,
    view_log.embedding_client,
    view_log.embedding_route,
        CASE
            WHEN ((view_log.embedding_client)::text ~~ '%-preview'::text) THEN true
            ELSE false
        END AS is_preview,
    view_log.has_access,
    view_log.context,
    view_log.embedding_sdk_version,
    view_log.metabase_version,
    view_log.auth_method,
    view_log.tenant_id,
    view_log.embedding_hostname,
    view_log.embedding_path,
    view_log.user_agent,
    view_log.sanitized_user_agent,
    view_log.ip_address
   FROM public.view_log;
--;;
ALTER TABLE public.view_log ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.view_log_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
--;;
CREATE TABLE public.workspace (
    id integer NOT NULL,
    name character varying(254) NOT NULL,
    creator_id integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);
--;;
COMMENT ON TABLE public.workspace IS 'Groups one or more databases with override credentials and per-database schema config';
--;;
COMMENT ON COLUMN public.workspace.id IS 'Unique ID';
--;;
COMMENT ON COLUMN public.workspace.name IS 'Display name of the workspace';
--;;
COMMENT ON COLUMN public.workspace.creator_id IS 'User who created this workspace';
--;;
COMMENT ON COLUMN public.workspace.created_at IS 'When this workspace was created';
--;;
COMMENT ON COLUMN public.workspace.updated_at IS 'When this workspace was last updated';
--;;
CREATE TABLE public.workspace_database (
    id integer NOT NULL,
    workspace_id integer NOT NULL,
    database_id integer NOT NULL,
    database_details text NOT NULL,
    output_namespace character varying(254) NOT NULL,
    input_schemas text NOT NULL,
    status character varying(20) DEFAULT 'unprovisioned'::character varying NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);
--;;
COMMENT ON TABLE public.workspace_database IS 'Associates a workspace with a database, with override credentials and schema config';
--;;
COMMENT ON COLUMN public.workspace_database.id IS 'Unique ID';
--;;
COMMENT ON COLUMN public.workspace_database.workspace_id IS 'The workspace this row belongs to';
--;;
COMMENT ON COLUMN public.workspace_database.database_id IS 'The underlying database this row configures';
--;;
COMMENT ON COLUMN public.workspace_database.database_details IS 'JSON-encoded override connection details';
--;;
COMMENT ON COLUMN public.workspace_database.output_namespace IS 'Driver-opaque namespace string where workspace output tables are written (schema on Postgres-shaped drivers, database name on MySQL)';
--;;
COMMENT ON COLUMN public.workspace_database.input_schemas IS 'JSON array of input schema names';
--;;
COMMENT ON COLUMN public.workspace_database.status IS 'Provisioning state';
--;;
COMMENT ON COLUMN public.workspace_database.created_at IS 'When this row was created';
--;;
COMMENT ON COLUMN public.workspace_database.updated_at IS 'When this row was last updated';
--;;
ALTER TABLE public.workspace_database ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.workspace_database_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
--;;
ALTER TABLE public.workspace ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME public.workspace_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);
--;;
